// v3ca01_records_value_equality / ex1 - with-expressions and deconstruction.

namespace CSharpDojo.V3CA01_Records;

/// <summary>A seat in a venue: a row letter and a number within that row.</summary>
public record Seat(string Row, int Number)
{
    /// <summary>The next seat along the same row.</summary>
    public Seat NextSeat() => this with { Number = Number + 1 };

    /// <summary>The printed label, for example "A12".</summary>
    public string Label()
    {
        var (row, number) = this;
        return $"{row}{number}";
    }

    /// <summary>True when both seats sit in the same row.</summary>
    public bool SameRowAs(Seat other) => Row == other.Row;
}

