// v3ca01_records_value_equality / ex2 - class, record and record struct equality.

namespace CSharpDojo.V3CA01_Records;

/// <summary>A record: value equality is generated.</summary>
public record Tag(string Name);

/// <summary>A plain class: inherits reference equality from object.</summary>
public class Label
{
    /// <summary>Creates a label.</summary>
    public Label(string name) => Name = name;

    /// <summary>The label text.</summary>
    public string Name { get; }
}

/// <summary>A readonly record struct: value equality, no boxing on the typed path.</summary>
public readonly record struct Cell(int Row, int Column);

/// <summary>Reports how each of the three kinds answers "are these two the same?".</summary>
public static class EqualitySurvey
{
    /// <summary>Compares two identically built instances of each type.</summary>
    public static string Report()
    {
        bool tag = new Tag("urgent") == new Tag("urgent");
        bool label = new Label("urgent").Equals(new Label("urgent"));
        bool cell = new Cell(2, 3) == new Cell(2, 3);

        object boxedLeft = new Cell(2, 3);
        object boxedRight = new Cell(2, 3);
        bool boxedCell = boxedLeft.Equals(boxedRight);

        return $"tag={tag} label={label} cell={cell} boxedCell={boxedCell}";
    }
}

