// v3ca01_records_value_equality / ex3 - structural equality over an array member.

namespace CSharpDojo.V3CA01_Records;

/// <summary>
/// A named, ordered list of track titles. Two playlists are the same value when
/// the names match and the tracks match element by element, in order.
/// </summary>
public record Playlist(string Name, string[] Tracks)
{
    /// <summary>Structural equality: the generated version compared the arrays by reference.</summary>
    public virtual bool Equals(Playlist? other) =>
        other is not null
        && EqualityContract == other.EqualityContract
        && Name == other.Name
        && Tracks.AsSpan().SequenceEqual(other.Tracks.AsSpan());

    /// <summary>Hashes every track, in order, so the hash agrees with Equals.</summary>
    public override int GetHashCode()
    {
        HashCode hash = new HashCode();
        hash.Add(EqualityContract);
        hash.Add(Name);
        foreach (string track in Tracks)
        {
            hash.Add(track);
        }

        return hash.ToHashCode();
    }
}

