namespace CSharpDojo.V3CA01_Records;

/// <summary>
/// A percentage discount between 0 and 100 inclusive. The check lives in the
/// init accessor because a with-expression bypasses the constructor entirely.
/// </summary>
public record Discount
{
    private readonly int _percent;

    /// <summary>Creates a discount, validating through the property setter.</summary>
    public Discount(int percent) => Percent = percent;

    /// <summary>The discount percentage; assignment is range-checked on every path.</summary>
    public int Percent
    {
        get => _percent;
        init
        {
            if (value is < 0 or > 100)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(Percent), value, "A discount must be between 0 and 100 inclusive.");
            }

            _percent = value;
        }
    }
}

