using System.Text;

namespace CSharpDojo.V3CA01_Records;

/// <summary>
/// An API credential pair. ToString deliberately never prints the token, so a
/// stray log line or debugger watch cannot leak it.
/// </summary>
public record Credentials(string User, string Token)
{
    /// <summary>
    /// Writes the printed members between the braces that ToString supplies.
    /// Returns true to tell any derived record that a separator is needed.
    /// </summary>
    protected virtual bool PrintMembers(StringBuilder builder)
    {
        builder.Append("User = ").Append(User);
        builder.Append(", Token = ***");
        builder.Append(", Fingerprint = ").Append(Fingerprint());
        return true;
    }

    /// <summary>The last two characters of the token, lower-cased, or "??" when it is too short.</summary>
    private string Fingerprint() =>
        Token.Length >= 2 ? Token[^2..].ToLowerInvariant() : "??";
}

