// v3ca01_records_value_equality / ex6 - EqualityContract and a deliberate opt-out.

namespace CSharpDojo.V3CA01_Records;

/// <summary>A shape with a number of straight sides.</summary>
public record Shape(int Sides);

/// <summary>A circle: no sides, and a distinct equality contract.</summary>
public record Circle() : Shape(0);

/// <summary>Demonstrations of how record equality treats a hierarchy.</summary>
public static class ShapeFacts
{
    /// <summary>
    /// Compares a Shape and a Circle holding identical data through Shape-typed
    /// variables. The answer is false, and it is false in both directions,
    /// because the generated Equals compares EqualityContract - the runtime type
    /// - before it looks at any member. That is what keeps equality symmetric.
    /// </summary>
    public static bool BaseEqualsDerived()
    {
        Shape plain = new Shape(0);
        Shape circle = new Circle();
        return plain == circle;
    }

    /// <summary>
    /// A second, weaker comparison: same geometry regardless of runtime type.
    /// It lives in a named method rather than an Equals override, because every
    /// hash-based collection in the BCL believes Equals.
    /// </summary>
    public static bool SameGeometryAs(Shape left, Shape right) => left.Sides == right.Sides;
}

