// v3ca01_records_value_equality / ex7 - case-insensitive record struct as a dictionary key.

namespace CSharpDojo.V3CA01_Records;

/// <summary>
/// A stock-keeping unit code. Codes are compared ordinal case-insensitively, so
/// "AB-1" and "ab-1" are one key - and the hash uses the same comparer, so the
/// dictionary looks in the bucket the comparison expects.
/// </summary>
public readonly record struct SkuKey(string Code)
{
    /// <summary>Ordinal, case-insensitive comparison. No boxing: this is the IEquatable overload.</summary>
    public bool Equals(SkuKey other) =>
        StringComparer.OrdinalIgnoreCase.Equals(Code, other.Code);

    /// <summary>Hash from the same comparer that decides equality.</summary>
    public override int GetHashCode() =>
        StringComparer.OrdinalIgnoreCase.GetHashCode(Code);
}

/// <summary>Stock levels by SKU code, insensitive to the caller's casing.</summary>
public sealed class SkuIndex
{
    private readonly Dictionary<SkuKey, int> _stock = new();

    /// <summary>Records the stock level for a code, replacing any earlier level.</summary>
    public void Add(string code, int stock) => _stock[new SkuKey(code)] = stock;

    /// <summary>Finds the stock level for a code whatever its casing.</summary>
    public bool TryLookup(string code, out int stock) =>
        _stock.TryGetValue(new SkuKey(code), out stock);
}

