// v3ca01_records_value_equality / ex8 - immutable aggregate, structural equality, cached hash.

using System.Collections.Immutable;

namespace CSharpDojo.V3CA01_Records;

/// <summary>One line of a basket: a SKU and how many of it.</summary>
public readonly record struct BasketLine(string Sku, int Quantity);

/// <summary>
/// An immutable basket. Equality is structural over the ordered lines; the hash
/// is computed once per instance and deliberately excluded from equality.
/// </summary>
public record Basket
{
    private readonly ImmutableArray<BasketLine> _lines;
    private readonly int _hash;

    /// <summary>Creates a basket from an ordered set of lines.</summary>
    public Basket(ImmutableArray<BasketLine> lines) => Lines = lines;

    /// <summary>
    /// The lines, in order. The init accessor is written by hand so that every
    /// construction path - including a with-expression - refreshes the cache.
    /// </summary>
    public ImmutableArray<BasketLine> Lines
    {
        get => _lines;
        init
        {
            _lines = value;
            _hash = ComputeHash(value);
        }
    }

    /// <summary>A basket with one more line at the end.</summary>
    public Basket Add(BasketLine line) => this with { Lines = Lines.Add(line) };

    /// <summary>A basket without the line at the given index.</summary>
    public Basket RemoveAt(int index) => this with { Lines = Lines.RemoveAt(index) };

    /// <summary>A basket with one line swapped for another.</summary>
    public Basket Replace(int index, BasketLine line) =>
        this with { Lines = Lines.SetItem(index, line) };

    /// <summary>Structural equality over the lines. The cached hash takes no part.</summary>
    public virtual bool Equals(Basket? other) =>
        other is not null
        && EqualityContract == other.EqualityContract
        && _hash == other._hash
        && _lines.AsSpan().SequenceEqual(other._lines.AsSpan());

    /// <summary>The hash computed at construction time.</summary>
    public override int GetHashCode() => _hash;

    private static int ComputeHash(ImmutableArray<BasketLine> lines)
    {
        HashCode hash = new HashCode();
        foreach (BasketLine line in lines)
        {
            hash.Add(line);
        }

        return hash.ToHashCode();
    }
}

