// v3ca01_records_value_equality / challenge - replaying deduplicated changes onto a snapshot.

using System.Collections.Immutable;
using System.Text;

namespace CSharpDojo.V3CA01_Records;

/// <summary>A single field assignment. Value equality is what makes deduplication possible.</summary>
public readonly record struct Change(string Field, string Value);

/// <summary>
/// An immutable set of field values built by applying changes in order. A change
/// identical to one already applied is ignored; a change with a new value for a
/// known field overwrites it.
/// </summary>
public record Snapshot
{
    private Snapshot(
        ImmutableDictionary<string, string> fields,
        ImmutableHashSet<Change> applied,
        int appliedCount)
    {
        Fields = fields;
        Applied = applied;
        AppliedCount = appliedCount;
    }

    /// <summary>The empty snapshot: no fields, nothing applied.</summary>
    public static Snapshot Empty { get; } = new Snapshot(
        ImmutableDictionary<string, string>.Empty,
        ImmutableHashSet<Change>.Empty,
        0);

    /// <summary>The current field values.</summary>
    public ImmutableDictionary<string, string> Fields { get; init; }

    /// <summary>Every change this snapshot's lineage has already applied.</summary>
    public ImmutableHashSet<Change> Applied { get; init; }

    /// <summary>How many changes actually took effect.</summary>
    public int AppliedCount { get; init; }

    /// <summary>Applies one change, or returns this snapshot when it is an exact repeat.</summary>
    public Snapshot Apply(Change change)
    {
        if (Applied.Contains(change))
        {
            return this;
        }

        return this with
        {
            Fields = Fields.SetItem(change.Field, change.Value),
            Applied = Applied.Add(change),
            AppliedCount = AppliedCount + 1,
        };
    }

    /// <summary>Applies every change in order.</summary>
    public Snapshot ApplyAll(IEnumerable<Change> changes)
    {
        Snapshot current = this;
        foreach (Change change in changes)
        {
            current = current.Apply(change);
        }

        return current;
    }

    /// <summary>Prints the fields sorted by name, so the rendering is stable across runs.</summary>
    protected virtual bool PrintMembers(StringBuilder builder)
    {
        bool first = true;
        foreach (KeyValuePair<string, string> pair in Fields.OrderBy(p => p.Key, StringComparer.Ordinal))
        {
            if (!first)
            {
                builder.Append(", ");
            }

            builder.Append(pair.Key).Append(" = ").Append(pair.Value);
            first = false;
        }

        return !first;
    }
}

