// v3ca01_records_value_equality / review1 - excluding a non-identifying field from equality.

namespace CSharpDojo.V3CA01_Records;

/// <summary>
/// One temperature reading. Two measurements are the same value when the sensor
/// and the temperature match: the capture time is real business data, but a
/// chattery sensor repeats the same reading and the pipeline deduplicates on
/// value, so the timestamp must not identify the reading.
/// </summary>
public record Measurement(string Sensor, double Celsius, DateTimeOffset CapturedAt)
{
    /// <summary>Equality over the sensor and the temperature only.</summary>
    public virtual bool Equals(Measurement? other) =>
        other is not null
        && EqualityContract == other.EqualityContract
        && string.Equals(Sensor, other.Sensor, StringComparison.Ordinal)
        // Equals, not ==: double.NaN == double.NaN is false, while
        // double.NaN.Equals(double.NaN) is true. A hash container needs the
        // second answer, or a NaN reading could never be found again.
        && Celsius.Equals(other.Celsius);

    /// <summary>The same two members that Equals uses, and no others.</summary>
    public override int GetHashCode() => HashCode.Combine(Sensor, Celsius);

    /// <summary>The same reading, stamped at a new time.</summary>
    public Measurement Recapture(DateTimeOffset at) => this with { CapturedAt = at };
}

