namespace CSharpDojo.V3CA02_PatternMatching;

/// <summary>Classification of HTTP status codes.</summary>
public static class HttpFacts
{
    /// <summary>The class of response a status code belongs to.</summary>
    public static string Category(int code) => code switch
    {
        < 100 or >= 600     => "invalid",
        >= 100 and < 200    => "informational",
        >= 200 and < 300    => "success",
        >= 300 and < 400    => "redirect",
        >= 400 and < 500    => "client error",
        _                   => "server error",
    };

    /// <summary>
    /// True when repeating the request could plausibly succeed: a timeout, a
    /// rate limit, or a server-side failure other than "not implemented",
    /// which will still not be implemented on the second attempt.
    /// </summary>
    public static bool IsRetryable(int code) => code switch
    {
        408 or 429                              => true,
        >= 500 and < 600 and not 501            => true,
        _                                       => false,
    };
}

