// v3ca02_pattern_matching / ex2 - nested property patterns, guards and arm order.

namespace CSharpDojo.V3CA02_PatternMatching;

/// <summary>A customer and their ordering history.</summary>
public record Customer(string Name, bool IsMember, int OrdersThisYear);

/// <summary>Where an order is going.</summary>
public record Address(string Country, string PostCode);

/// <summary>An order awaiting a shipping quote.</summary>
public record Order(decimal Total, Address? Destination, Customer? Customer);

/// <summary>Shipping prices, most specific rule first.</summary>
public static class Shipping
{
    private const int FrequentThreshold = 12;

    /// <summary>
    /// The shipping cost, or -1 when the order has no destination. Every arm is
    /// null-safe: a property pattern fails to match a null receiver rather than
    /// dereferencing it, so no explicit null checks appear below the first arm.
    /// </summary>
    public static decimal Quote(Order order) => order switch
    {
        { Destination: null } => -1m,

        { Total: > 100, Customer.IsMember: true } => 0m,

        { Destination.Country: "GB", Customer: { OrdersThisYear: var orders } }
            when orders > FrequentThreshold => 0m,

        { Destination.Country: "GB" } => 4.99m,

        { Total: > 100 } => 7.99m,

        _ => 12.99m,
    };
}

