// v3ca02_pattern_matching / ex3 - tuple patterns and positional patterns.

namespace CSharpDojo.V3CA02_PatternMatching;

/// <summary>The three moves.</summary>
public enum Move
{
    /// <summary>Blunts scissors.</summary>
    Rock,

    /// <summary>Wraps rock.</summary>
    Paper,

    /// <summary>Cuts paper.</summary>
    Scissors,
}

/// <summary>A traffic light: a colour and the seconds until it changes.</summary>
public record Light(string Colour, int SecondsLeft);

/// <summary>Two small state tables written as patterns.</summary>
public static class Rules
{
    /// <summary>Which side wins, as a tuple pattern over both moves at once.</summary>
    public static string Beats(Move left, Move right) => (left, right) switch
    {
        (var a, var b) when a == b               => "draw",
        (Move.Rock, Move.Scissors)               => "left",
        (Move.Scissors, Move.Paper)              => "left",
        (Move.Paper, Move.Rock)                  => "left",
        _                                        => "right",
    };

    /// <summary>
    /// The next state of the light. The countdown arm sits first: without it,
    /// the colour arms would fire on every call and the timer would be
    /// decoration.
    /// </summary>
    public static Light Next(Light light) => light switch
    {
        (_, > 0)        => light with { SecondsLeft = light.SecondsLeft - 1 },
        ("green", 0)    => new Light("amber", 4),
        ("amber", 0)    => new Light("red", 30),
        ("red", 0)      => new Light("green", 25),
        _               => new Light("red", 30),
    };
}

