// v3ca02_pattern_matching / ex4 - list and slice patterns over a command line.

namespace CSharpDojo.V3CA02_PatternMatching;

/// <summary>Classifies a command line by its shape.</summary>
public static class Cli
{
    /// <summary>
    /// The command the arguments describe. Every arm is a list or slice pattern,
    /// so the length constraints are part of the shape rather than separate
    /// comparisons, and the empty case cannot be forgotten.
    /// </summary>
    public static string Parse(string[] args) => args switch
    {
        [] => "usage",
        ["help"] => "help",
        ["add", var name] => $"add {name}",
        ["remove", var name, "--force"] => $"remove {name} (forced)",
        [.., "--verbose"] and var all => $"verbose: {all.Length} args",
        // [] and [var head, ..] between them cover every possible length, so the
        // switch is exhaustive and needs no discard arm.
        [var head, .. var rest] => $"{head} + {rest.Length} more",
    };
}

