// v3ca02_pattern_matching / ex5 - a closed hierarchy and a provably exhaustive switch.

namespace CSharpDojo.V3CA02_PatternMatching;

/// <summary>
/// A payment. The private constructor closes the hierarchy: only the nested
/// records below can derive from it, so a switch over them is exhaustive and
/// needs no discard arm.
/// </summary>
public abstract record Payment
{
    private Payment()
    {
    }

    /// <summary>A card payment, charged a percentage fee.</summary>
    public sealed record Card(string Last4, decimal Amount) : Payment;

    /// <summary>Cash: no fee.</summary>
    public sealed record Cash(decimal Amount) : Payment;

    /// <summary>A voucher: a flat handling fee.</summary>
    public sealed record Voucher(string Code) : Payment;

    /// <summary>A bank transfer: a flat fee, whatever the amount.</summary>
    public sealed record BankTransfer(string Iban, decimal Amount) : Payment;
}

/// <summary>Payment processing fees.</summary>
public static class Fees
{
    // Comment out any arm below and the compiler answers with
    // warning CS8509: the switch expression does not handle all possible values
    // of type 'Payment' - and names the case you removed.

    /// <summary>The fee charged for taking this payment.</summary>
    public static decimal For(Payment payment) => payment switch
    {
        Payment.Card { Amount: var amount } =>
            Math.Round(amount * 0.014m, 2, MidpointRounding.AwayFromZero),
        Payment.Cash => 0m,
        Payment.Voucher => 0.25m,
        Payment.BankTransfer => 0.20m,
    };
}

