// v3ca02_pattern_matching / ex6 - null patterns cannot be intercepted by an operator.

namespace CSharpDojo.V3CA02_PatternMatching;

/// <summary>A type whose equality operators deliberately lie about null.</summary>
public sealed class Sneaky
{
    /// <summary>Always false, even when both sides are null.</summary>
    public static bool operator ==(Sneaky? left, Sneaky? right) => false;

    /// <summary>Always true, even when both sides are null.</summary>
    public static bool operator !=(Sneaky? left, Sneaky? right) => true;

    /// <inheritdoc />
    public override bool Equals(object? obj) => false;

    /// <inheritdoc />
    public override int GetHashCode() => 0;
}

/// <summary>Null tests that no type author can subvert.</summary>
public static class NullSafe
{
    /// <summary>
    /// True when the reference is null. The constant null pattern lowers to a
    /// reference comparison with no call site, so a type with custom equality
    /// operators cannot change the answer.
    /// </summary>
    public static bool IsMissing<T>(T? value)
        where T : class => value is null;

    /// <summary>How many entries in the sequence are genuinely null references.</summary>
    public static int CountMissing(IEnumerable<object?> values)
    {
        int missing = 0;
        foreach (object? value in values)
        {
            if (value is null)
            {
                missing++;
            }
        }

        return missing;
    }
}

