// v3ca02_pattern_matching / ex7 - recursive evaluation with structural simplification.

namespace CSharpDojo.V3CA02_PatternMatching;

/// <summary>A tiny arithmetic expression tree. The hierarchy is closed.</summary>
public abstract record Expr
{
    private Expr()
    {
    }

    /// <summary>A literal.</summary>
    public sealed record Num(int Value) : Expr;

    /// <summary>Addition.</summary>
    public sealed record Add(Expr Left, Expr Right) : Expr;

    /// <summary>Multiplication.</summary>
    public sealed record Mul(Expr Left, Expr Right) : Expr;

    /// <summary>Negation.</summary>
    public sealed record Neg(Expr Inner) : Expr;
}

/// <summary>Evaluates expressions, folding a few algebraic identities on the way.</summary>
public static class Evaluator
{
    /// <summary>How many times Eval has been entered since the last Reset.</summary>
    public static int EvalCount { get; private set; }

    /// <summary>Clears the evaluation counter.</summary>
    public static void Reset() => EvalCount = 0;

    /// <summary>
    /// The value of the expression. The simplification arms match on the shape
    /// of the children, so an absorbed subtree is never walked at all - the
    /// discard in Mul(Num(0), _) is what makes the short circuit real.
    /// </summary>
    public static int Eval(Expr expr)
    {
        EvalCount++;

        return expr switch
        {
            // Absorbing element: the other side is never evaluated.
            Expr.Mul(Expr.Num(0), _) => 0,
            Expr.Mul(_, Expr.Num(0)) => 0,

            // Identity elements.
            Expr.Add(Expr.Num(0), var other) => Eval(other),
            Expr.Add(var other, Expr.Num(0)) => Eval(other),
            Expr.Mul(Expr.Num(1), var other) => Eval(other),
            Expr.Mul(var other, Expr.Num(1)) => Eval(other),

            // Double negation.
            Expr.Neg(Expr.Neg(var inner)) => Eval(inner),

            // General cases.
            Expr.Num(var value) => value,
            Expr.Add(var left, var right) => Eval(left) + Eval(right),
            Expr.Mul(var left, var right) => Eval(left) * Eval(right),
            Expr.Neg(var inner) => -Eval(inner),
        };
    }
}

