// v3ca02_pattern_matching / challenge - a routing table written as one switch expression.

namespace CSharpDojo.V3CA02_PatternMatching;

/// <summary>A matched route: the handler name and the captured parameter, if any.</summary>
public readonly record struct Route(string Name, string? Parameter);

/// <summary>Matches an HTTP method and path segments against a fixed route table.</summary>
public static class Router
{
    /// <summary>
    /// The first route whose shape and method match. Overlapping rules are
    /// ordered most specific first: the numeric-id arms sit above the general
    /// two-segment arm, which needs no negated condition as a result.
    ///
    /// The id stays a string. Parsing it inside the guard with int.TryParse
    /// would work - an out variable declared in a guard is in scope in the arm -
    /// but it would also normalise "007" to "7", losing the caller's text.
    /// </summary>
    public static Route Match(string method, string[] segments) => (method, segments) switch
    {
        ("GET", []) => new Route("home", null),
        ("GET", ["health"]) => new Route("health", null),

        ("GET", ["orders"]) => new Route("orders.index", null),
        ("POST", ["orders"]) => new Route("orders.create", null),

        ("GET", ["orders", var id, "items"]) when IsId(id) => new Route("orders.items", id),
        ("GET", ["orders", var id]) when IsId(id) => new Route("orders.show", id),
        ("DELETE", ["orders", var id]) when IsId(id) => new Route("orders.destroy", id),
        ("GET", ["orders", var reference]) => new Route("orders.by-reference", reference),

        (var verb, [.., "debug"]) => new Route("debug", verb),

        _ => new Route("not-found", null),
    };

    // IsAsciiDigit, not char.IsDigit: the latter accepts every Unicode decimal
    // digit, including scripts an id column will refuse.
    private static bool IsId(string value) =>
        value.Length > 0 && value.All(char.IsAsciiDigit);
}

