// v3ca03_generics_constraints / ex1 - the Try shape for an unconstrained T.

namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>Lookups that do not need a sentinel value.</summary>
public static class Sequences
{
    /// <summary>
    /// Finds the first matching element. Returns false and leaves `found` at
    /// default when nothing matches - which is why the result is a bool: for
    /// T = int, default is 0, and 0 is a perfectly good element.
    /// </summary>
    public static bool TryFirst<T>(IEnumerable<T> items, Func<T, bool> match, out T? found)
    {
        foreach (T item in items)
        {
            if (match(item))
            {
                found = item;
                return true;
            }
        }

        found = default;
        return false;
    }

    /// <summary>The first matching element, or the caller's fallback.</summary>
    public static T FirstOr<T>(IEnumerable<T> items, Func<T, bool> match, T fallback)
    {
        foreach (T item in items)
        {
            if (match(item))
            {
                return item;
            }
        }

        return fallback;
    }
}

