// v3ca03_generics_constraints / ex2 - one constraint per unlocked operation.

namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>Anything that can render itself as text.</summary>
public interface IRenderable
{
    /// <summary>The rendered form.</summary>
    string Format();
}

/// <summary>Five generic methods, each needing exactly one constraint.</summary>
public static class Archaeology
{
    // new() unlocks: constructing a T with no arguments.
    /// <summary>A freshly constructed T.</summary>
    public static T Fresh<T>()
        where T : new() => new T();

    // class? unlocks: comparing a T to null.
    /// <summary>True when the reference is null.</summary>
    public static bool IsAbsent<T>(T value)
        where T : class? => value is null;

    // struct unlocks: T? meaning Nullable<T>, which has a real "no value" state.
    /// <summary>The value, or no value at all.</summary>
    public static T? Lift<T>(T value, bool keep)
        where T : struct => keep ? value : (T?)null;

    // IRenderable unlocks: calling Format() on a T.
    /// <summary>The value's own rendering.</summary>
    public static string Render<T>(T value)
        where T : IRenderable => value.Format();

    // notnull unlocks: using T as a dictionary key without a nullability warning.
    /// <summary>How many times each distinct item appears.</summary>
    public static Dictionary<T, int> Tally<T>(IEnumerable<T> items)
        where T : notnull
    {
        Dictionary<T, int> counts = new();
        foreach (T item in items)
        {
            counts[item] = counts.TryGetValue(item, out int seen) ? seen + 1 : 1;
        }

        return counts;
    }
}

