namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>Linear searches that work for any T, with or without a caller's comparer.</summary>
public static class Search
{
    /// <summary>
    /// The index of the first element equal to the value, using the type's own
    /// notion of equality, or -1.
    /// EqualityComparer&lt;T&gt;.Default dispatches to IEquatable&lt;T&gt;.Equals
    /// when T implements it, so a value type never boxes on this path.
    /// </summary>
    public static int IndexOf<T>(IReadOnlyList<T> items, T value) =>
        IndexOf(items, value, EqualityComparer<T>.Default);

    /// <summary>The index of the first element the comparer considers equal, or -1.</summary>
    public static int IndexOf<T>(IReadOnlyList<T> items, T value, IEqualityComparer<T> comparer)
    {
        ArgumentNullException.ThrowIfNull(items);
        ArgumentNullException.ThrowIfNull(comparer);

        for (int index = 0; index < items.Count; index++)
        {
            if (comparer.Equals(items[index], value))
            {
                return index;
            }
        }

        return -1;
    }
}

