// v3ca03_generics_constraints / ex4 - notnull keys, and a factory instead of new().

namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>
/// A small, deliberately non-thread-safe memo table.
/// The new() constraint lives on a generic method rather than on the class:
/// putting it on the class would stop anyone caching a string, an
/// ImmutableArray, or any struct whose real constructor takes arguments.
/// </summary>
public sealed class Cache<TKey, TValue>
    where TKey : notnull
{
    private readonly Dictionary<TKey, TValue> _entries = new();

    /// <summary>How many entries are stored.</summary>
    public int Count => _entries.Count;

    /// <summary>
    /// The cached value, computing and storing it on a miss. The factory is not
    /// invoked when the key is already present.
    /// </summary>
    public TValue GetOrAdd(TKey key, Func<TKey, TValue> factory)
    {
        ArgumentNullException.ThrowIfNull(factory);

        if (_entries.TryGetValue(key, out TValue? existing))
        {
            return existing;
        }

        TValue created = factory(key);
        _entries[key] = created;
        return created;
    }

    /// <summary>The cached value, if there is one.</summary>
    public bool TryGet(TKey key, out TValue? value) => _entries.TryGetValue(key, out value);
}

/// <summary>
/// The new()-constrained convenience sits out here, as an extension, so the
/// constraint applies to this one call rather than to every use of the cache.
/// </summary>
public static class CacheExtensions
{
    /// <summary>
    /// The cached value, default-constructing it on a miss. For a struct this
    /// produces the all-zero value, which the type's real constructor might
    /// never have allowed - one more reason to prefer the factory overload.
    /// </summary>
    public static TValue GetOrAddNew<TKey, TValue>(this Cache<TKey, TValue> cache, TKey key)
        where TKey : notnull
        where TValue : new() =>
        cache.GetOrAdd(key, _ => new TValue());
}

