namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>An animal with a name.</summary>
public class Animal
{
    /// <summary>Creates an animal.</summary>
    public Animal(string name) => Name = name;

    /// <summary>What to call it.</summary>
    public string Name { get; }
}

/// <summary>A dog.</summary>
public sealed class Dog : Animal
{
    /// <summary>Creates a dog.</summary>
    public Dog(string name)
        : base(name)
    {
    }
}

/// <summary>A cat.</summary>
public sealed class Cat : Animal
{
    /// <summary>Creates a cat.</summary>
    public Cat(string name)
        : base(name)
    {
    }
}

/// <summary>
/// A box you can only read from, so it is safe to treat a box of dogs as a box
/// of animals. Adding `void Put(T item)` below makes the declaration illegal:
/// error CS1961 - invalid variance, T must be invariantly valid.
/// </summary>
public interface IReadOnlyBox<out T>
{
    /// <summary>What is in the box.</summary>
    T Item { get; }

    // void Put(T item);   // error CS1961
}

/// <summary>A box holding exactly one thing.</summary>
public sealed class Box<T> : IReadOnlyBox<T>
{
    /// <summary>Creates a box around an item.</summary>
    public Box(T item) => Item = item;

    /// <inheritdoc />
    public T Item { get; }
}

/// <summary>Variance, and the pre-generics version of the same idea.</summary>
public static class Zoo
{
    /// <summary>The name of whatever animal the box holds.</summary>
    public static string NameOf(IReadOnlyBox<Animal> box) => box.Item.Name;

    /// <summary>
    /// Arrays have been covariant since C# 1, with no compiler check - so the
    /// unsafe store is legal at compile time and fails at run time. Every store
    /// into a reference-type array pays for this.
    /// </summary>
    public static string ArrayCovariance()
    {
        Dog[] dogs = [new Dog("rex")];
        Animal[] animals = dogs;

        try
        {
            animals[0] = new Cat("mog");
            return "no exception";
        }
        catch (ArrayTypeMismatchException ex)
        {
            return ex.GetType().Name;
        }
    }
}

