// v3ca03_generics_constraints / ex6 - one implementation for every numeric type.

using System.Numerics;

namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>Aggregations written once, over INumber&lt;T&gt;.</summary>
public static class Maths
{
    /// <summary>
    /// The total. Wrapping arithmetic: Sum(new[] { int.MaxValue, 1 }) is
    /// int.MinValue, exactly as a hand-written int loop would be.
    /// </summary>
    public static T Sum<T>(IEnumerable<T> values)
        where T : INumber<T>
    {
        T total = T.Zero;
        foreach (T value in values)
        {
            total += value;
        }

        return total;
    }

    /// <summary>
    /// The arithmetic mean, using T's own division - so the mean of four ints
    /// is an int, and 10 / 4 is 2. A mean that promotes to double is a
    /// different method with a different signature.
    /// </summary>
    public static T Mean<T>(IReadOnlyCollection<T> values)
        where T : INumber<T>
    {
        if (values.Count == 0)
        {
            throw new InvalidOperationException("The sequence contains no elements.");
        }

        return Sum(values) / T.CreateChecked(values.Count);
    }

    /// <summary>
    /// The total, throwing on overflow. `checked` selects T's checked addition
    /// operator, which int implements by throwing and double implements as the
    /// ordinary add - IEEE 754 saturates to infinity rather than overflowing.
    /// </summary>
    public static T SumChecked<T>(IEnumerable<T> values)
        where T : INumber<T>
    {
        T total = T.Zero;
        foreach (T value in values)
        {
            checked
            {
                total += value;
            }
        }

        return total;
    }
}

