// v3ca03_generics_constraints / ex7 - static abstract interface members as a factory contract.

using System.Globalization;

namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>
/// A type that can build itself from a row of text cells. The curiously
/// recurring constraint is what lets the interface name the implementing type:
/// remove it and T.FromRow fails to compile with error CS0704 at the call site.
/// </summary>
/// <typeparam name="TSelf">The implementing type.</typeparam>
public interface IFromRow<TSelf>
    where TSelf : IFromRow<TSelf>
{
    /// <summary>Builds an instance from one row.</summary>
    static abstract TSelf FromRow(string[] cells);

    /// <summary>How many cells a valid row has.</summary>
    static abstract int ExpectedColumns { get; }
}

/// <summary>A user row.</summary>
public sealed record User(int Id, string Name) : IFromRow<User>
{
    /// <inheritdoc />
    public static User FromRow(string[] cells) =>
        new(int.Parse(cells[0], CultureInfo.InvariantCulture), cells[1]);

    /// <inheritdoc />
    public static int ExpectedColumns => 2;
}

/// <summary>A sensor reading row.</summary>
public sealed record Reading(string Sensor, double Value) : IFromRow<Reading>
{
    /// <inheritdoc />
    public static Reading FromRow(string[] cells) =>
        new(cells[0], double.Parse(cells[1], CultureInfo.InvariantCulture));

    /// <inheritdoc />
    public static int ExpectedColumns => 2;
}

/// <summary>Materialises rows into any type that knows how to build itself.</summary>
public static class RowReader
{
    /// <summary>How many rows the last ReadAll call rejected.</summary>
    public static int Skipped { get; private set; }

    /// <summary>
    /// Every well-formed row, materialised. No reflection and no factory
    /// delegate: the type argument carries the construction logic, and the JIT
    /// resolves T.FromRow when it specialises this method.
    /// </summary>
    public static List<T> ReadAll<T>(IEnumerable<string[]> rows)
        where T : IFromRow<T>
    {
        Skipped = 0;
        List<T> results = [];

        foreach (string[] row in rows)
        {
            if (row.Length != T.ExpectedColumns)
            {
                Skipped++;
                continue;
            }

            results.Add(T.FromRow(row));
        }

        return results;
    }
}

exercises.hints:
## Hint 1

Two constraints, two jobs. `INumber<T>` gives you `+`, `<`, `>` and `T.Zero`.
`IMinMaxValue<T>` gives you `T.MaxValue` and `T.MinValue`, and those are what
let you seed the running extremes without a flag.

Seeding a minimum with the largest possible value is an old trick, and it has
exactly one failure mode. Work out what it is before you write the empty-case
branch.

## Hint 2

The loop, in outline:

```csharp
T min = T.MaxValue;
T max = T.MinValue;
T sum = T.Zero;
int count = 0;

foreach (T value in values)
{
    if (value < min) min = value;
    if (value > max) max = value;
    sum += value;
    count++;
}
```

Comparison operators work because `INumber<T>` includes
`IComparisonOperators<T, T, bool>`. You do not need `CompareTo` and you should
not use it — the operator is what the type author defined for ordering.

## Hint 3

The empty case is a branch after the loop, not inside it: if `count` is zero,
return a summary of zeros rather than the seeds. Anything else hands the caller
`int.MaxValue` as a minimum, and that number will travel a long way before
anyone questions it.

Left to you: whether `Describe` should instead return `Summary<T>?` or throw for
an empty sequence. All three are defensible; the gate wants zeros, and the
requirement is that you say which you chose and why.

