// v3ca03_generics_constraints / ex8 - count, min, max and sum in one pass, no boxing.

using System.Numerics;

namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>The result of describing a sequence of numbers.</summary>
/// <typeparam name="T">The numeric element type.</typeparam>
public readonly record struct Summary<T>(int Count, T Min, T Max, T Sum)
    where T : INumber<T>;

/// <summary>Single-pass descriptive statistics over any numeric type.</summary>
public static class Stats
{
    /// <summary>
    /// Count, minimum, maximum and total, computed in exactly one pass. The
    /// extremes are seeded from T.MaxValue and T.MinValue so no "seen anything
    /// yet" flag is needed - which is precisely why the empty sequence needs
    /// its own answer: returning the seeds would report a minimum of
    /// int.MaxValue, a number that would travel a long way before anyone
    /// questioned it. An empty sequence is reported as all zeros.
    /// </summary>
    public static Summary<T> Describe<T>(IEnumerable<T> values)
        where T : INumber<T>, IMinMaxValue<T>
    {
        T min = T.MaxValue;
        T max = T.MinValue;
        T sum = T.Zero;
        int count = 0;

        foreach (T value in values)
        {
            if (value < min)
            {
                min = value;
            }

            if (value > max)
            {
                max = value;
            }

            sum += value;
            count++;
        }

        return count == 0
            ? new Summary<T>(0, T.Zero, T.Zero, T.Zero)
            : new Summary<T>(count, min, max, sum);
    }
}

