// v3ca03_generics_constraints / challenge - Result with Map, Bind, Match and a folding sum.

using System.Numerics;

namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>
/// Either a value or an error. A readonly struct, so the success path allocates
/// nothing; the two static factories are the only constructors, so a result is
/// never in a third state; and Match is the only reader, so no caller can take
/// the value without answering for the error case.
/// </summary>
/// <typeparam name="TValue">The success type.</typeparam>
/// <typeparam name="TError">The failure type.</typeparam>
public readonly struct Result<TValue, TError>
{
    private readonly TValue _value;
    private readonly TError _error;

    private Result(TValue value, TError error, bool isOk)
    {
        _value = value;
        _error = error;
        IsOk = isOk;
    }

    /// <summary>True when this result carries a value.</summary>
    public bool IsOk { get; }

    /// <summary>A successful result.</summary>
    public static Result<TValue, TError> Ok(TValue value) => new(value, default!, true);

    /// <summary>A failed result.</summary>
    public static Result<TValue, TError> Fail(TError error) => new(default!, error, false);

    /// <summary>Transforms the value; an error passes through untouched.</summary>
    public Result<TNext, TError> Map<TNext>(Func<TValue, TNext> project) =>
        IsOk
            ? Result<TNext, TError>.Ok(project(_value))
            : Result<TNext, TError>.Fail(_error);

    /// <summary>
    /// Transforms the value with a projection that may itself fail. Unlike Map,
    /// the projection's result is not wrapped again - which is what stops a
    /// chain accumulating Result&lt;Result&lt;T, E&gt;, E&gt;.
    /// </summary>
    public Result<TNext, TError> Bind<TNext>(Func<TValue, Result<TNext, TError>> project) =>
        IsOk ? project(_value) : Result<TNext, TError>.Fail(_error);

    /// <summary>The only way to read the contents: both cases must be answered.</summary>
    public TOut Match<TOut>(Func<TValue, TOut> onOk, Func<TError, TOut> onError) =>
        IsOk ? onOk(_value) : onError(_error);
}

/// <summary>Aggregations over sequences of results.</summary>
public static class Results
{
    /// <summary>
    /// The total of every successful value, or the first error. A foreach with
    /// an early return, not Aggregate: Aggregate cannot stop, so it would
    /// evaluate the elements after the failure.
    /// </summary>
    public static Result<T, TError> SumOf<T, TError>(IEnumerable<Result<T, TError>> results)
        where T : INumber<T>
    {
        T total = T.Zero;

        foreach (Result<T, TError> result in results)
        {
            if (!result.IsOk)
            {
                // Map on a failed result carries the error through untouched and
                // retypes the value side - which is exactly what is wanted here,
                // and a small demonstration of why Map has that signature.
                return result.Map(_ => T.Zero);
            }

            total = result.Match(value => total + value, _ => total);
        }

        return Result<T, TError>.Ok(total);
    }
}

