// v3ca03_generics_constraints / review1 - a generic half-open range, and where each constraint lives.

using System.Numerics;

namespace CSharpDojo.V3CA03_GenericsConstraints;

/// <summary>
/// A half-open range: Start is included, End is excluded. Constrained on
/// IComparable&lt;T&gt; only, so it works for DateOnly and string as well as
/// numbers - adding INumber&lt;T&gt; here would exclude every ordered type that
/// is not arithmetic.
/// </summary>
/// <typeparam name="T">The ordered element type.</typeparam>
public readonly record struct Range<T>(T Start, T End)
    where T : IComparable<T>
{
    /// <summary>True when the range contains no values at all.</summary>
    public bool IsEmpty => Start.CompareTo(End) >= 0;

    /// <summary>True when the value is at or after Start and strictly before End.</summary>
    public bool Contains(T value) =>
        !IsEmpty && Start.CompareTo(value) <= 0 && value.CompareTo(End) < 0;

    /// <summary>
    /// True when the two ranges share at least one value. Both comparisons are
    /// strict, so ranges that merely touch - [1,5) and [5,9) - do not overlap.
    /// </summary>
    public bool Overlaps(Range<T> other) =>
        !IsEmpty && !other.IsEmpty
        && Start.CompareTo(other.End) < 0
        && other.Start.CompareTo(End) < 0;

    /// <summary>
    /// The values in both ranges, or null when they do not meet.
    /// Range&lt;T&gt;? is Nullable&lt;Range&lt;T&gt;&gt; - a real "no value"
    /// state, which an empty range would not be: an empty range is a range that
    /// happens to contain nothing, and the caller would have to guess which of
    /// the two meanings was intended.
    /// </summary>
    public Range<T>? Intersect(Range<T> other)
    {
        if (!Overlaps(other))
        {
            return null;
        }

        T start = Start.CompareTo(other.Start) >= 0 ? Start : other.Start;
        T end = End.CompareTo(other.End) <= 0 ? End : other.End;
        return new Range<T>(start, end);
    }
}

/// <summary>Operations that need arithmetic, and so cannot live on Range&lt;T&gt;.</summary>
public static class Ranges
{
    /// <summary>
    /// How wide the range is. Zero for an empty range, so Length agrees with
    /// Contains rather than reporting a negative width.
    /// </summary>
    public static TNumber Length<TNumber>(Range<TNumber> range)
        where TNumber : INumber<TNumber>, IComparable<TNumber> =>
        range.IsEmpty ? TNumber.Zero : range.End - range.Start;
}

