    public Config(IReadOnlyDictionary<string, string?> entries) => _entries = entries;

    /// <summary>
    /// The value for a key, when there is one. The attribute is what lets a
    /// caller who checks the bool use the value without a second null test:
    /// the relationship between the return value and the out parameter cannot
    /// be expressed in the type system.
    /// </summary>
    public bool TryGet(string key, [NotNullWhen(true)] out string? value)
    {
