namespace CSharpDojo.V3CA04_NullableReferences;

/// <summary>Someone an order belongs to.</summary>
public sealed class Customer
{
    /// <summary>Creates a customer.</summary>
    public Customer(string name) => Name = name;

    /// <summary>Their name.</summary>
    public string Name { get; }
}

/// <summary>An order, which may be from a guest.</summary>
public class Order
{
    /// <summary>The customer, if the order is not a guest checkout.</summary>
    public virtual Customer? Customer { get; set; }

    /// <summary>What is owed.</summary>
    public decimal Total { get; set; }
}

/// <summary>Rendering an order to a receipt line.</summary>
public static class Receipts
{
    /// <summary>
    /// The receipt line for an order.
    ///
    /// The customer is copied into a local for two separate reasons.
    ///
    /// The compiler's reason: a property access is a method call, and nothing
    /// promises two calls return the same thing, so narrowing the null state of
    /// order.Customer does not survive to the next access. A local, once
    /// assigned, cannot change, so the state holds.
    ///
    /// The machine's reason: this reads the property once instead of three
    /// times. When the property is a dictionary lookup, a lazily built cache or
    /// an ORM navigation that loads on access, that is three times the work -
    /// and, for a property that really does return something new each time, a
    /// self-inconsistent result.
    /// </summary>
    public static string Render(Order order)
    {
        if (order.Customer is { } customer)
        {
            return $"{customer.Name} ({customer.Name.Length}) owes {order.Total}";
        }

        return $"guest owes {order.Total}";
    }
}

