using System.Diagnostics.CodeAnalysis;

namespace CSharpDojo.V3CA04_NullableReferences;

/// <summary>A fixed-size character ring buffer.</summary>
public sealed class RingBuffer
{
    private char[] _data;
    private int _head;

    /// <summary>Creates a buffer of the given capacity.</summary>
    public RingBuffer(int capacity) => Allocate(capacity);

    /// <summary>How many characters the buffer holds.</summary>
    public int Capacity => _data.Length;

    /// <summary>
    /// True when the buffer has storage. MemberNotNullWhen is the attribute for
    /// a deferred or optional initialisation, where a caller has to ask first -
    /// a lazily opened stream wrapper, say. Here allocation is guaranteed by
    /// the constructor, so it is always true; it is present to contrast with
    /// the unconditional promise on Allocate.
    /// </summary>
    [MemberNotNullWhen(true, nameof(_data))]
    public bool IsAllocated => _data.Length > 0;

    /// <summary>The raw buffer contents, in index order.</summary>
    public string Contents => new string(_data);

    /// <summary>Replaces the storage and rewinds to the start.</summary>
    public void Resize(int capacity) => Allocate(capacity);

    /// <summary>Writes one character and advances, wrapping at the end.</summary>
    public void Write(char value)
    {
        _data[_head] = value;
        _head = (_head + 1) % _data.Length;
    }

    /// <summary>
    /// Assigns the buffer. The attribute is what lets the constructor's flow
    /// analysis see through this call - and it is checked here, so a path that
    /// left _data unassigned would warn on this method rather than at some
    /// distant caller.
    /// </summary>
    [MemberNotNull(nameof(_data))]
    private void Allocate(int capacity)
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(capacity);
        _data = new char[capacity];
        _head = 0;
    }
}

