using System.Diagnostics.CodeAnalysis;

namespace CSharpDojo.V3CA04_NullableReferences;

/// <summary>Whitespace normalisation that preserves the null/blank distinction.</summary>
public static class Text
{
    /// <summary>
    /// Trims and collapses runs of whitespace. Returns null only for a null
    /// argument - which the attribute records, so a caller passing a real
    /// string gets a non-nullable result and writes no null check.
    /// </summary>
    [return: NotNullIfNotNull(nameof(text))]
    public static string? Clean(string? text)
    {
        if (text is null)
        {
            return null;
        }

        string[] parts = text.Split(
            (char[]?)null, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        return string.Join(' ', parts);
    }
}

/// <summary>User settings, where clearing a value means "use the default".</summary>
public sealed class Settings
{
    private const string DefaultTheme = "light";

    private string _theme = DefaultTheme;

    /// <summary>
    /// The theme. Assigning null resets it to the default, so the setter is
    /// more permissive than the getter - which is exactly what AllowNull
    /// records. Declaring the property string? instead would make every reader
    /// handle a null the getter never produces.
    /// </summary>
    [AllowNull]
    public string Theme
    {
        get => _theme;
        set => _theme = value ?? DefaultTheme;
    }
}

