using System.Diagnostics.CodeAnalysis;

namespace CSharpDojo.V3CA04_NullableReferences;

/// <summary>Guard clauses that tell the compiler what they do.</summary>
public static class Guard
{
    /// <summary>Always throws. The attribute is what stops the caller's flow analysis here.</summary>
    [DoesNotReturn]
    public static void Missing(string name) =>
        throw new InvalidOperationException($"{name} is required.");

    /// <summary>
    /// Throws when the condition holds. DoesNotReturnIf(true) is the mirror of
    /// Debug.Assert's DoesNotReturnIf(false): after this call the condition was
    /// false, and the compiler propagates that back to whatever the condition
    /// was testing.
    /// </summary>
    public static void Against([DoesNotReturnIf(true)] bool condition, string message)
    {
        if (condition)
        {
            throw new InvalidOperationException(message);
        }
    }
}

/// <summary>Address formatting, guarded rather than null-checked inline.</summary>
public static class Shipping
{
    /// <summary>The single-line shipping label.</summary>
    public static string Label(string? address, string? postcode)
    {
        if (address is null)
        {
            Guard.Missing(nameof(address));
        }

        Guard.Against(postcode is null, "postcode is required.");

        return $"{address.Trim()} {postcode.ToUpperInvariant()}";
    }
}

