namespace CSharpDojo.V3CA04_NullableReferences;

/// <summary>An invoice header.</summary>
public sealed record Invoice(string Number);

/// <summary>One invoice line.</summary>
public sealed record Line(string Description, decimal Amount);

/// <summary>Invoice rendering, hardened at the boundary.</summary>
public static class Invoices
{
    /// <summary>
    /// Renders an invoice summary.
    ///
    /// The parameters are annotated non-nullable and are also checked at run
    /// time, because the two do different jobs. The annotation is a contract
    /// the compiler enforces for callers it can see: they get a warning at
    /// their own build, which is far cheaper than an exception at ours. The
    /// check covers everyone the compiler cannot see - assemblies built before
    /// C# 8, deserialisers, reflection, generated proxies, and any caller who
    /// silenced the warning with `!`.
    ///
    /// The helpers need no parameter name: each takes a
    /// [CallerArgumentExpression] argument that the compiler fills in with the
    /// source text of the argument, so ParamName is "invoice" without anyone
    /// typing it - and it cannot drift when the parameter is renamed.
    /// </summary>
    public static string Render(Invoice invoice, string culture, IReadOnlyList<Line> lines)
    {
        ArgumentNullException.ThrowIfNull(invoice);
        ArgumentException.ThrowIfNullOrWhiteSpace(culture);
        ArgumentNullException.ThrowIfNull(lines);

        if (lines.Count == 0)
        {
            return $"{invoice.Number} ({culture}): no lines";
        }

        decimal total = lines.Sum(line => line.Amount);
        return $"{invoice.Number} ({culture}): {lines.Count} lines totalling {total}";
    }
}

