// v3ca04_nullable_reference_types / ex8 - required members and a merge the compiler can prove.

using System.Diagnostics.CodeAnalysis;

namespace CSharpDojo.V3CA04_NullableReferences;

/// <summary>A partially filled profile: any member may be missing.</summary>
public sealed record DraftProfile(string? DisplayName, string? Email, string? Timezone);

/// <summary>A complete profile. Every member is required and non-nullable.</summary>
public sealed class Profile
{
    /// <summary>Creates an empty profile; every required member must be set by the initialiser.</summary>
    public Profile()
    {
    }

    /// <summary>
    /// Creates a complete profile.
    ///
    /// [SetsRequiredMembers] excuses callers of this constructor from the
    /// object-initialiser requirement. The cost is precisely that excusal: add
    /// a fourth required member later and every object-initialiser call site
    /// fails to compile - which is the point of `required` - while this
    /// constructor keeps compiling and silently leaves the new member unset.
    /// </summary>
    [SetsRequiredMembers]
    public Profile(string displayName, string email, string timezone)
    {
        DisplayName = displayName;
        Email = email;
        Timezone = timezone;
    }

    /// <summary>The name to show.</summary>
    public required string DisplayName { get; init; }

    /// <summary>The contact address.</summary>
    public required string Email { get; init; }

    /// <summary>The IANA timezone id.</summary>
    public required string Timezone { get; init; }
}

/// <summary>Combining partial profiles into complete ones.</summary>
public static class Profiles
{
    /// <summary>
    /// Takes the first non-null value for each member, preferring the primary
    /// draft. Every member is bound by a pattern, so the compiler proves all
    /// three are non-null before the constructor is reached - no null-forgiving
    /// operator and no runtime argument check are needed.
    /// </summary>
    public static bool TryMerge(DraftProfile primary, DraftProfile fallback, out Profile? merged)
    {
        if ((primary.DisplayName ?? fallback.DisplayName) is { } displayName
            && (primary.Email ?? fallback.Email) is { } email
            && (primary.Timezone ?? fallback.Timezone) is { } timezone)
        {
            merged = new Profile(displayName, email, timezone);
            return true;
        }

        merged = null;
        return false;
    }
}

