using System.Diagnostics.CodeAnalysis;
using System.Globalization;

namespace CSharpDojo.V3CA04_NullableReferences;

/// <summary>Fully bound, fully non-null server options.</summary>
public sealed record ServerOptions(string Host, int Port, string Scheme, TimeSpan Timeout);

/// <summary>The outcome of a bind: options, or the reasons there are none.</summary>
public sealed record BindResult(ServerOptions? Options, IReadOnlyList<string> Errors)
{
    /// <summary>
    /// True when binding produced options. Defined as "Options is not null"
    /// rather than "Errors is empty" so that the MemberNotNullWhen promise is
    /// something the compiler can actually verify.
    /// </summary>
    [MemberNotNullWhen(true, nameof(Options))]
    public bool Succeeded => Options is not null;
}

/// <summary>Binds a string dictionary into strongly typed options.</summary>
public static class OptionsBinder
{
    private const string DefaultScheme = "https";

    /// <summary>
    /// Reads every key, collecting all problems before deciding. Keys are
    /// validated in a fixed order so the error list is deterministic - a
    /// foreach over the dictionary would report in hash order, which is not
    /// contractual and makes the output untestable.
    /// </summary>
    public static BindResult Bind(IReadOnlyDictionary<string, string?> source)
    {
        List<string> errors = [];

        string? host = RequireText(source, "host", errors);
        int? port = RequirePort(source, errors);
        string? scheme = ReadScheme(source, errors);
        TimeSpan? timeout = ReadTimeout(source, errors);

        if (errors.Count == 0
            && host is { } boundHost
            && port is { } boundPort
            && scheme is { } boundScheme
            && timeout is { } boundTimeout)
        {
            return new BindResult(
                new ServerOptions(boundHost, boundPort, boundScheme, boundTimeout), errors);
        }

        return new BindResult(null, errors);
    }

    private static string? RequireText(
        IReadOnlyDictionary<string, string?> source, string key, List<string> errors)
    {
        // A missing key and a present-but-null value are the same thing here.
        if (!source.TryGetValue(key, out string? value) || string.IsNullOrWhiteSpace(value))
        {
            errors.Add($"{key} is required");
            return null;
        }

        return value;
    }

    private static int? RequirePort(IReadOnlyDictionary<string, string?> source, List<string> errors)
    {
        if (!source.TryGetValue("port", out string? text) || string.IsNullOrWhiteSpace(text))
        {
            errors.Add("port is required");
            return null;
        }

        if (!int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out int port))
        {
            errors.Add("port must be an integer");
            return null;
        }

        if (port is < 1 or > 65535)
        {
            errors.Add("port must be between 1 and 65535");
            return null;
        }

        return port;
    }

    private static string? ReadScheme(IReadOnlyDictionary<string, string?> source, List<string> errors)
    {
        // Three branches, not two: absent is a default, present-and-wrong is an
        // error. Collapsing them turns a typo into a silent https.
        if (!source.TryGetValue("scheme", out string? text) || string.IsNullOrWhiteSpace(text))
        {
            return DefaultScheme;
        }

        if (text is not ("http" or "https"))
        {
            errors.Add("scheme must be http or https");
            return null;
        }

        return text;
    }

    private static TimeSpan? ReadTimeout(IReadOnlyDictionary<string, string?> source, List<string> errors)
    {
        if (!source.TryGetValue("timeout", out string? text) || string.IsNullOrWhiteSpace(text))
        {
            return TimeSpan.FromSeconds(30);
        }

        if (!int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out int seconds))
        {
            errors.Add("timeout must be a whole number of seconds");
            return null;
        }

        return TimeSpan.FromSeconds(seconds);
    }
}

