// v3ca04_nullable_reference_types / review1 - a chain where null is the honest terminator.

using System.Diagnostics.CodeAnalysis;
using System.Text;

namespace CSharpDojo.V3CA04_NullableReferences;

/// <summary>One link in a singly linked chain.</summary>
public sealed class Node
{
    /// <summary>Creates a node, optionally linked to the next one.</summary>
    public Node(string value, Node? next = null)
    {
        Value = value;
        Next = next;
    }

    /// <summary>The value at this link.</summary>
    public string Value { get; }

    /// <summary>
    /// The next link, or null at the end.
    ///
    /// Why nullable rather than a sentinel end-of-chain node? Because "no next
    /// link" is a real state carrying no data, and every alternative encodes it
    /// worse: a sentinel object means every consumer must know about it and
    /// compare against it - a null check wearing a costume, plus an allocation
    /// - and a bool alongside a non-nullable Next means two fields that can
    /// disagree. The point of this sector is annotations that tell the truth,
    /// not annotations that say "never null" everywhere.
    /// </summary>
    public Node? Next { get; set; }
}

/// <summary>Walks over chains that may be empty and always end.</summary>
public static class Chain
{
    /// <summary>How many links the chain has.</summary>
    public static int Length(Node? head)
    {
        int count = 0;
        for (Node? current = head; current is not null; current = current.Next)
        {
            count++;
        }

        return count;
    }

    /// <summary>Every value, separated.</summary>
    public static string Join(Node? head, string separator)
    {
        StringBuilder builder = new();
        for (Node? current = head; current is not null; current = current.Next)
        {
            if (builder.Length > 0)
            {
                builder.Append(separator);
            }

            builder.Append(current.Value);
        }

        return builder.ToString();
    }

    /// <summary>The final link, or null for an empty chain.</summary>
    public static Node? Last(Node? head)
    {
        Node? current = head;
        while (current?.Next is not null)
        {
            current = current.Next;
        }

        return current;
    }

    /// <summary>The first link with the given value, if there is one.</summary>
    public static bool TryFind(Node? head, string value, [NotNullWhen(true)] out Node? found)
    {
        for (Node? current = head; current is not null; current = current.Next)
        {
            if (current.Value == value)
            {
                found = current;
                return true;
            }
        }

        found = null;
        return false;
    }
}

