// v3ca05_linq_deferred_cost / ex1 - predicting how many elements a chain reads.

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>Chains whose element-visit counts are the answer.</summary>
public static class Visits
{
    /// <summary>
    /// Builds a query and never enumerates it. Predicted Reads: 0 - calling
    /// Where and Select allocates two iterators and runs no user code at all.
    /// </summary>
    public static int BuildOnly(CountingSource source)
    {
        IEnumerable<int> query = source.Where(n => n > 0).Select(n => n * 2);
        _ = query;
        return 0;
    }

    /// <summary>
    /// Takes the first two positives, doubled. Predicted Reads: 3 - Take(2)
    /// stops asking once it has two outputs, and Where needed three inputs
    /// (3, -1, 4) to produce them.
    /// </summary>
    public static int FirstTwo(CountingSource source) =>
        source.Where(n => n > 0).Select(n => n * 2).Take(2).Sum();

    /// <summary>
    /// The largest value. Predicted Reads: 6 - OrderByDescending is deferred but
    /// buffering: on the first MoveNext it reads the whole source and sorts it,
    /// so First() costs a full pass plus an O(n log n) sort to answer a
    /// question one pass would answer.
    /// </summary>
    public static int SortedFirst(CountingSource source) =>
        source.OrderByDescending(n => n).First();

    /// <summary>
    /// Materialises, then counts. Predicted Reads: 6 - all from the ToList.
    /// Count() on a List&lt;T&gt; short-circuits to the Count property and
    /// walks nothing.
    /// </summary>
    public static int CountAfterMaterialise(CountingSource source)
    {
        List<int> materialised = source.ToList();
        return materialised.Count();
    }
}

