// v3ca05_linq_deferred_cost / ex2 - enumerate once, and do not copy what is already a collection.

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>Summaries that respect the one-enumeration rule.</summary>
public static class Reports
{
    /// <summary>
    /// Count, total and largest, from a single pass.
    ///
    /// TryGetNonEnumeratedCount asks the source whether it knows its own size:
    /// true for arrays, lists and other collections, false for a yield method or
    /// a file reader. Only in the false case is a copy made - so a caller who
    /// already holds a List&lt;T&gt; is not punished, and a caller holding a
    /// one-shot iterator still gets a correct answer.
    /// </summary>
    public static string Summarise<T>(IEnumerable<T> items, Func<T, decimal> amount)
    {
        if (!items.TryGetNonEnumeratedCount(out int count))
        {
            List<T> buffered = items.ToList();
            items = buffered;
            count = buffered.Count;
        }

        if (count == 0)
        {
            return "0 items";
        }

        decimal total = 0m;
        decimal largest = decimal.MinValue;

        foreach (T item in items)
        {
            decimal value = amount(item);
            total += value;
            if (value > largest)
            {
                largest = value;
            }
        }

        return $"{count} items, total {total}, largest {largest}";
    }
}

