// v3ca05_linq_deferred_cost / ex3 - three ways to find a minimum, and what each costs.

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>An order with a total.</summary>
public sealed record Order(string Id, decimal Total);

/// <summary>Finding the cheapest order, with the comparison count as evidence.</summary>
public static class Cheapest
{
    /// <summary>
    /// Sorts everything and takes the front. Establishes the complete ordering
    /// of every element to answer a question about one of them, and buffers the
    /// whole source plus a key array and an index array on the way.
    /// </summary>
    public static (Order? Order, int Comparisons) BySorting(IEnumerable<Order> orders)
    {
        CountingComparer comparer = new();
        Order? cheapest = orders.OrderBy(order => order.Total, comparer).FirstOrDefault();
        return (cheapest, comparer.Comparisons);
    }

    /// <summary>
    /// One pass, one candidate held. MinBy returns null for an empty sequence
    /// rather than throwing the way Min does - Min returns the key, which for a
    /// value type has no sensible empty answer, while MinBy returns the element.
    /// </summary>
    public static (Order? Order, int Comparisons) ByMinBy(IEnumerable<Order> orders)
    {
        CountingComparer comparer = new();
        Order? cheapest = orders.MinBy(order => order.Total, comparer);
        return (cheapest, comparer.Comparisons);
    }

    /// <summary>The same work, written out: n - 1 comparisons and no allocation.</summary>
    public static (Order? Order, int Comparisons) ByLoop(IEnumerable<Order> orders)
    {
        CountingComparer comparer = new();
        Order? best = null;

        foreach (Order order in orders)
        {
            if (best is null || comparer.Compare(order.Total, best.Total) < 0)
            {
                best = order;
            }
        }

        return (best, comparer.Comparisons);
    }
}

