// v3ca05_linq_deferred_cost / ex4 - iterator methods, and validating at the right time.

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>Hand-written streaming operators.</summary>
public static class Lazily
{
    /// <summary>
    /// Filters lazily.
    ///
    /// The public method contains no yield, so it runs immediately and its
    /// argument checks throw at the call. A single method containing both the
    /// checks and the yield would be compiled into a state machine, and the
    /// checks would not run until the first MoveNext - producing an exception
    /// at the foreach, in another method, far from the mistake.
    /// </summary>
    public static IEnumerable<T> WhereLazy<T>(this IEnumerable<T> source, Func<T, bool> predicate)
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentNullException.ThrowIfNull(predicate);
        return Iterator(source, predicate);

        static IEnumerable<T> Iterator(IEnumerable<T> source, Func<T, bool> predicate)
        {
            foreach (T item in source)
            {
                if (predicate(item))
                {
                    yield return item;
                }
            }
        }
    }

    /// <summary>Projects lazily.</summary>
    public static IEnumerable<TResult> SelectLazy<T, TResult>(
        this IEnumerable<T> source, Func<T, TResult> project)
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentNullException.ThrowIfNull(project);
        return Iterator(source, project);

        static IEnumerable<TResult> Iterator(IEnumerable<T> source, Func<T, TResult> project)
        {
            foreach (T item in source)
            {
                yield return project(item);
            }
        }
    }

    /// <summary>
    /// Yields while the predicate holds, plus the first element that breaks it.
    /// Yield first, test second: that ordering is what makes it inclusive, and
    /// it is why this cannot be built out of TakeWhile.
    /// </summary>
    public static IEnumerable<T> TakeWhileInclusive<T>(
        this IEnumerable<T> source, Func<T, bool> predicate)
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentNullException.ThrowIfNull(predicate);
        return Iterator(source, predicate);

        static IEnumerable<T> Iterator(IEnumerable<T> source, Func<T, bool> predicate)
        {
            foreach (T item in source)
            {
                yield return item;
                if (!predicate(item))
                {
                    yield break;
                }
            }
        }
    }
}

