// v3ca05_linq_deferred_cost / ex5 - classifying operators, and sorting once instead of three times.

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>One sale.</summary>
public sealed record Sale(string Region, decimal Amount);

/// <summary>Which operators buffer, and which do not.</summary>
public static class Audit
{
    /// <summary>
    /// How an operator behaves.
    ///
    /// Distinct counts as streaming because it yields each new element as soon
    /// as it sees it - it never waits for the end of the input. It does carry a
    /// growing HashSet of everything seen, so it streams in latency and not in
    /// memory, which is a distinction the one-word answer hides.
    /// </summary>
    public static string Classify(string operatorName) => operatorName switch
    {
        "Where" or "Select" or "SelectMany" or "Take" or "Skip" or "Zip"
            or "Concat" or "Distinct" => "streaming",

        "OrderBy" or "OrderByDescending" or "Reverse" or "GroupBy" => "buffering",

        "ToList" or "ToArray" or "Count" or "Sum" or "Any" or "First"
            or "ToDictionary" => "immediate",

        _ => "unknown",
    };
}

/// <summary>Sales reporting, sorted once.</summary>
public static class Sales
{
    /// <summary>
    /// Highest region, lowest region, and the top three.
    ///
    /// Materialising the sorted sequence is the whole fix. Naming the query
    /// without ToList would not help: a deferred query is a recipe, so each
    /// consumer of the name re-reads the source and re-sorts it.
    /// </summary>
    public static string Report(IEnumerable<Sale> sales)
    {
        List<Sale> sorted = sales.OrderByDescending(sale => sale.Amount).ToList();

        if (sorted.Count == 0)
        {
            return "no sales";
        }

        string top = sorted[0].Region;
        string bottom = sorted[^1].Region;
        IEnumerable<string> topThree = sorted.Take(3).Select(sale => sale.Region);

        return $"{top}/{bottom}/{string.Join('+', topThree)}";
    }
}

