// v3ca05_linq_deferred_cost / ex6 - GroupBy, ToLookup, ToDictionary, and a mutated key.

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>A catalogue item with a deliberately mutable category.</summary>
public sealed class Item
{
    /// <summary>Creates an item.</summary>
    public Item(string category, string name)
    {
        Category = category;
        Name = name;
    }

    /// <summary>Which group it belongs to. Mutable so the key trap can be shown.</summary>
    public string Category { get; set; }

    /// <summary>Its name.</summary>
    public string Name { get; }
}

/// <summary>Four demonstrations of how grouping behaves.</summary>
public static class Grouping
{
    /// <summary>
    /// GroupBy is deferred: building it reads nothing. It feels eager because
    /// grouping feels like work that has to happen, and it does - on the first
    /// MoveNext, when it reads the entire source at once.
    /// </summary>
    public static int GroupByReads(CountingItems items)
    {
        IEnumerable<IGrouping<string, Item>> groups = items.GroupBy(item => item.Category);
        _ = groups;
        return items.Reads;
    }

    /// <summary>
    /// ToLookup is GroupBy's immediate twin: it reads everything now and hands
    /// back an indexable, reusable result. If the groups will be walked more
    /// than once, or looked up by key, this is the one you wanted.
    /// </summary>
    public static int LookupReads(CountingItems items)
    {
        ILookup<string, Item> lookup = items.ToLookup(item => item.Category);
        _ = lookup;
        return items.Reads;
    }

    /// <summary>
    /// ToDictionary throws on a duplicate key, loudly. That is a feature: the
    /// alternatives - first wins, last wins - both lose data in silence.
    /// </summary>
    public static string DictionaryOutcome(IEnumerable<Item> items)
    {
        try
        {
            Dictionary<string, Item> byCategory = items.ToDictionary(item => item.Category);
            _ = byCategory;
            return "ok";
        }
        catch (ArgumentException ex)
        {
            return ex.GetType().Name;
        }
    }

    /// <summary>
    /// Mutating a key after grouping strands the entry: the lookup filed the
    /// item under its old category and nothing moves it. Asking under the new
    /// category searches a different bucket and finds nothing.
    /// </summary>
    public static string MutatedKeyOutcome()
    {
        Item spade = new("tools", "spade");
        ILookup<string, Item> lookup = new[] { spade }.ToLookup(item => item.Category);

        spade.Category = "garden";

        return lookup["garden"].Any() ? "found" : "missing";
    }
}

