// v3ca05_linq_deferred_cost / ex7 - a try that wraps the query construction, not the query.

using System.Globalization;

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>Where a deferred query's exception actually surfaces.</summary>
public static class Parsing
{
    /// <summary>
    /// Broken on purpose. Select builds an object and calls int.Parse never, so
    /// the try wraps nothing that can fail; the FormatException is thrown by
    /// MoveNext inside string.Join, in a different method, past the catch.
    /// </summary>
    public static string ParseBroken(IEnumerable<string> lines)
    {
        IEnumerable<int> numbers;
        try
        {
            numbers = lines.Select(line => int.Parse(line, CultureInfo.InvariantCulture));
        }
        catch (FormatException)
        {
            return "bad input";
        }

        return string.Join(',', numbers);
    }

    /// <summary>Fixed by materialising inside the try, so the work happens where the catch can see it.</summary>
    public static string ParseEager(IEnumerable<string> lines)
    {
        try
        {
            List<int> numbers = lines
                .Select(line => int.Parse(line, CultureInfo.InvariantCulture))
                .ToList();
            return string.Join(',', numbers);
        }
        catch (FormatException)
        {
            return "bad input";
        }
    }

    /// <summary>
    /// Fixed by enumerating inside the try. string.Join drives the query, so the
    /// parsing happens under the catch without a materialised list.
    ///
    /// Which to ship: the eager one, in most codebases. It costs a list, and in
    /// exchange the try covers exactly the operation whose failure it claims to
    /// handle. The lazy version's try also spans string.Join itself, so a
    /// FormatException raised for an unrelated reason inside the consumer would
    /// be reported as "bad input" - a narrow lie that is hard to find later.
    /// Where the sequence is large enough that materialising matters, the lazy
    /// version wins and the try should be as narrow as it can be made.
    /// </summary>
    public static string ParseLazy(IEnumerable<string> lines)
    {
        try
        {
            return string.Join(',', lines.Select(line => int.Parse(line, CultureInfo.InvariantCulture)));
        }
        catch (FormatException)
        {
            return "bad input";
        }
    }
}

