// v3ca05_linq_deferred_cost / ex8 - turning a nested scan into a hash join.

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>A customer.</summary>
public sealed record Customer(int Id, string Name);

/// <summary>A sale against a customer.</summary>
public sealed record Sale2(int CustomerId, decimal Amount);

/// <summary>Flagging customers with a large sale, two ways.</summary>
public static class Flagging
{
    /// <summary>
    /// The shape people actually write. The Any inside the Where's lambda walks
    /// the sales sequence once per customer, so the cost is n x m sale visits -
    /// invisible in review, because each line is individually reasonable.
    /// </summary>
    public static (List<string> Names, int Visits) Quadratic(
        IReadOnlyList<Customer> customers, CountingSales sales)
    {
        List<string> names = customers
            .Where(customer => sales.Any(sale =>
                sale.CustomerId == customer.Id && sale.Amount > 100))
            .Select(customer => customer.Name)
            .Order(StringComparer.Ordinal)
            .ToList();

        return (names, sales.Visits);
    }

    /// <summary>
    /// One pass to build an index, then an O(1) lookup per customer - which is
    /// what a database would do with the same query, and for the same reason.
    /// The amount filter belongs in the index-building pass: move it to the
    /// customer side and it cannot be applied at all, because the set has
    /// dropped the amounts.
    /// </summary>
    public static (List<string> Names, int Visits) HashJoin(
        IReadOnlyList<Customer> customers, CountingSales sales)
    {
        HashSet<int> qualifying = sales
            .Where(sale => sale.Amount > 100)
            .Select(sale => sale.CustomerId)
            .ToHashSet();

        List<string> names = customers
            .Where(customer => qualifying.Contains(customer.Id))
            .Select(customer => customer.Name)
            .Order(StringComparer.Ordinal)
            .ToList();

        return (names, sales.Visits);
    }
}

