// v3ca05_linq_deferred_cost / challenge - five aggregates, one pass, over a one-shot source.

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>One line of a request log.</summary>
public sealed record LogLine(DateTimeOffset At, string Level, string Route, int Milliseconds);

/// <summary>What the analyser reports.</summary>
public sealed record Analysis(
    int Total,
    int Errors,
    long TotalMilliseconds,
    string SlowestRoute,
    int DistinctRoutes);

/// <summary>Two implementations of the same report.</summary>
public static class LogAnalyser
{
    /// <summary>
    /// The obvious LINQ version: five aggregates, five walks. Correct for a
    /// list, and impossible for a source that can only be read once.
    /// </summary>
    public static Analysis MultiPass(IReadOnlyList<LogLine> lines)
    {
        if (lines.Count == 0)
        {
            return new Analysis(0, 0, 0, string.Empty, 0);
        }

        return new Analysis(
            lines.Count,
            lines.Count(line => string.Equals(line.Level, "error", StringComparison.Ordinal)),
            lines.Sum(line => (long)line.Milliseconds),
            lines.MaxBy(line => line.Milliseconds)!.Route,
            lines.Select(line => line.Route).Distinct(StringComparer.Ordinal).Count());
    }

    /// <summary>
    /// The same report from one enumeration.
    ///
    /// The accumulator for the total is a long: milliseconds arrive as ints, and
    /// an int accumulator wraps silently somewhere past 2.1 billion.
    ///
    /// The slowest comparison is strictly greater, not greater-or-equal, so a
    /// tie keeps the line that appeared first - which is the specification, and
    /// is exactly the sort of detail that makes two implementations disagree on
    /// one data set in a hundred.
    /// </summary>
    public static Analysis SinglePass(IEnumerable<LogLine> lines)
    {
        ArgumentNullException.ThrowIfNull(lines);

        int total = 0;
        int errors = 0;
        long totalMilliseconds = 0;
        int slowest = -1;
        string slowestRoute = string.Empty;
        HashSet<string> routes = new(StringComparer.Ordinal);

        foreach (LogLine line in lines)
        {
            total++;

            if (string.Equals(line.Level, "error", StringComparison.Ordinal))
            {
                errors++;
            }

            totalMilliseconds += line.Milliseconds;
            routes.Add(line.Route);

            if (line.Milliseconds > slowest)
            {
                slowest = line.Milliseconds;
                slowestRoute = line.Route;
            }
        }

        return new Analysis(total, errors, totalMilliseconds, slowestRoute, routes.Count);
    }
}

