// v3ca05_linq_deferred_cost / review1 - predicting reads across three chains.

namespace CSharpDojo.V3CA05_LinqDeferredCost;

/// <summary>Chains whose read counts are predictable from the operators alone.</summary>
public static class Predictions
{
    /// <summary>
    /// Predicted Reads: 4. Distinct emits only new values, so the duplicate 2
    /// costs a read and produces nothing: 1 (new), 2 (new), 2 (duplicate),
    /// 3 (new) satisfies Take(3).
    /// </summary>
    public static (List<int> Result, int Reads) Chain1(CountingSource source)
    {
        List<int> result = source.Distinct().Take(3).ToList();
        return (result, source.Reads);
    }

    /// <summary>
    /// Predicted Reads: 3. SelectMany expands, so it needs fewer inputs than it
    /// produces outputs: 1 gives [1], 2 gives [2, 2] - three so far - and the
    /// second 2 supplies the fourth on its first element.
    /// </summary>
    public static (List<int> Result, int Reads) Chain2(CountingSource source)
    {
        List<int> result = source
            .SelectMany(n => Enumerable.Repeat(n, n))
            .Take(4)
            .ToList();
        return (result, source.Reads);
    }

    /// <summary>
    /// Predicted Reads: 8, the whole source. OrderByDescending buffers
    /// everything before it can yield the first element, so the Take(2)
    /// downstream limits nothing upstream of the sort.
    /// </summary>
    public static (List<int> Result, int Reads) Chain3(CountingSource source)
    {
        List<int> result = source
            .Distinct()
            .OrderByDescending(n => n)
            .Take(2)
            .ToList();
        return (result, source.Reads);
    }

    /// <summary>The one-sentence explanation, as it would read in a code review.</summary>
    public static string WhyChain3IsExpensive() =>
        "The OrderByDescending buffers the entire source before it can yield anything, "
        + "so the Take(2) cannot limit the work done upstream of the sort.";
}
